/// <summary>
/// MPJ_30779_PaymentPlus
/// Exception management for File states for the sources when import running in batch
/// Add the exact error message from the infolog into the error message field instead of just having a generic error message
/// </summary>
[ExtensionOf(tableStr(ERImportFormatRunFileSourceLogEntry))]
final class METERImportFormatRunFileSourceLogEntryTbl_Extension
{
}

Method.Source:
    /// <summary>
    /// When record is inserted and failed, get the detailed errors from infolog into ERImportFormatRunFileSourceLogEntry
    /// this is valid when a file is imported, moved or deleted 
    /// </summary>
    public void insert()
    {        
        SysInfologEnumerator        enumerator;
        SysInfologMessageStruct     msgStruct;
        Exception                   exception;
        str                         error;
        
        if (this.Failed == NoYes::Yes
        && this.ErrorDescription == "@ElectronicReporting:ImportOperationWasNotSuccessful")
        {
            enumerator = SysInfologEnumerator::newData(infolog.cut());

            while (enumerator.moveNext())
            {
                msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
                exception = enumerator.currentException();

                if (exception == Exception::Error)
                {
                    error = strfmt('%1 %2', error, msgStruct.message());
                    this.ErrorDescription += error;
                }
            }
        }
        next insert();
    }
